def parse_weekly(raw):
    count_str, body = raw.split("|", 1)
    rows = []
    for item in body.split(";"):
        d, o, h, l, c, v = item.split(",")
        y, m, day = d.split("/")
        iso = f"{int(y):04d}-{int(m):02d}-{int(day):02d}"
        rows.append({"date": iso, "o": float(o), "h": float(h), "l": float(l), "c": float(c), "v": int(float(v))})
    rows.sort(key=lambda r: r["date"])
    return rows


def parse_monthly(raw):
    count_str, body = raw.split("|", 1)
    rows = []
    for item in body.split(";"):
        d, o, h, l, c, v = item.split(",")
        y, m = d.split("/")
        iso = f"{int(y):04d}-{int(m):02d}-01"
        rows.append({"date": iso, "o": float(o), "h": float(h), "l": float(l), "c": float(c), "v": int(float(v))})
    rows.sort(key=lambda r: r["date"])
    return rows


def add_turnover(rows):
    for r in rows:
        r["turnover"] = round(r["c"] * r["v"])
    return rows


def main():
    with open(DATA_PATH, encoding="utf-8") as f:
        data = json.load(f)

    for stock in data["stocks"]:
        code = stock["code"]
        # daily: rename from "candles"
        if "candles" in stock:
            stock["daily"] = stock.pop("candles")
        if code in WEEKLY_RAW:
            stock["weekly"] = add_turnover(parse_weekly(WEEKLY_RAW[code]))
        if code in MONTHLY_RAW:
            stock["monthly"] = add_turnover(parse_monthly(MONTHLY_RAW[code]))

    from datetime import date
    data["generated"] = date.today().isoformat()
    data["source"] = (
        "Yahoo!ファイナンス（個別銘柄ヒストリカルデータ）を実際に取得。"
        "日足は毎営業日1本ずつ実データを追記。週足・月足は日足データから自動集計して更新。"
    )

    with open(DATA_PATH, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=1)

    for stock in data["stocks"]:
        print(stock["code"], stock["name"],
              "daily:", len(stock.get("daily", [])),
              "weekly:", len(stock.get("weekly", [])),
              "monthly:", len(stock.get("monthly", [])))


if __name__ == "__main__":
    main()
